/**
 * Slide-3 (`games/game-4` / `Weapon Hit 71 Senjata`) runtime for slide 1.
 *
 * Nothing here is redrawn. This file hosts slide 3's *own* code on slide 1:
 * `setSevenFire.ts`, `setSevenAnim.ts` and `setSevenWheel.ts` are verbatim
 * copies of slide 3's `Game.ts` (generated by `scripts/gen-set-seven.py`), the
 * shots are the real slide-3 `Projectile` subclasses, the stuck rounds are its
 * `drawStuckItem()`, the decals its `drawDecals()`, and the sounds its own
 * synthesizer. All of that was written against slide 3's game object; the shim
 * below is that object.
 *
 * Slide 1 keeps the rules: it moves the carrier round, decides when the wheel
 * is hit, and scores it. Slide 3 owns everything you see and hear — including
 * the way its wheel reacts (`feel`: the bounce spring, the rim flash, the size
 * pulse and the screen flash of its own `Game`). Impact hit-stop is deliberately
 * skipped so the wheel and controls stay responsive even on rapid hits.
 */
import { BatchableWheelLightning, K, Particles, type FX } from '../../../../games/game-4/src/game/particles';
import { WheelLightningCache } from './batchedWheelLightning';
import { newAnim, type StuckItem, type WeaponAnim, type WeaponId } from '../../../../games/game-4/src/game/weapons';
import type { Decal, Game } from '../../../../games/game-4/src/game/Game';
import { drawStuckItem } from '../../../../games/game-4/src/game/art';
import { FIRE_RECIPES } from './setSevenFire';
import { updateSevenAnim } from './setSevenAnim';
import { drawSevenDecals, updateSevenDecals, updateSevenStuck } from './setSevenWheel';
import type { SlideThreeId } from './setSevenArt';
import type { Projectile } from '../../../../games/game-4/src/game/projectiles';

const TAU = Math.PI * 2;

/** Best-effort cosmetic limits; protected/gameplay particles can exceed them. */
export const GOLDEN_PARTICLE_BUDGET = 300;
export const SLIDE_THREE_PARTICLE_BUDGET = 400;

/** What slide 1 does for slide 3 (the parts slide 1's own canvas owns). */
export interface SevenHooks {
  /** Screen shake, in slide 3's units (slide 1's shake is the same model). */
  shake(amount: number): void;
  /**
   * Paint into the wheel's own face canvas. The callback receives a context
   * centred on the wheel (slide 3's convention) and clipped to it.
   */
  paintWheel(draw: (c: CanvasRenderingContext2D) => void, radius: number): void;
  /** Slide-1 wheel geometry, refreshed every frame. */
  wheel(): { x: number; y: number; R: number; angle: number };
}

/** Slide-3's wheel object, shared with the projectile classes. */
export interface SevenWheel {
  x: number;
  y: number;
  R: number;
  angle: number;
  bumpY: number;
  bumpV: number;
  flash: number;
  flashColor: string;
  scale: number;
  intro: number;
  shakeT: number;
  shakeX: number;
}

/**
 * Slide 3's own reaction to a hit — what its `Game` moves, with its numbers:
 * the wheel bounce spring (`wheelImpact`: −26·power px/s into k 420 / c 22),
 * the rim flash (fades at 7/s, drawn at 0.6×), the shrink/grow size pulse
 * (k 130 / c 9) and the full-screen flash (fades at 2.2/s). Projectile
 * impact stops are ignored so consecutive hits don't appear to freeze play.
 */
export interface SevenFeel {
  bumpY: number;
  bumpV: number;
  rim: number;
  rimColor: string;
  pulseS: number;
  pulseV: number;
  flashA: number;
  flashColor: string;
  stop: number;
}

/**
 * The part of slide-3's `Game` the generated recipes and the projectile
 * classes touch. Slide 3's constructors take the real `Game` class, so the shim
 * is cast; this interface is what it actually provides.
 */
export interface SevenGame {
  particles: Particles;
  anim: WeaponAnim;
  wheel: SevenWheel;
  wheelGone: boolean;
  stuck: StuckItem[];
  time: number;
  addFX(f: FX): void;
  addWheelFX(f: FX): void;
  addDecal(d: Decal): void;
  paint(fn: (c: CanvasRenderingContext2D) => void): void;
  lens(x: number, y: number, r: number, s: number): void;
  shake(a: number): void;
  flashScreen(color: string, a: number): void;
  wheelImpact(power: number, color?: string): void;
  hitStop(t: number): void;
  after(delay: number, fn: () => void): void;
  pulseWheel(a: number): void;
  landed(it: StuckItem, clearDelay?: number): void;
  collide(p: Projectile, prev: number, tip: number): void;
}

/** Everything the generated slide-3 recipes expect from their host. */
export interface SevenHost {
  readonly g: Game;
  readonly particles: Particles;
  readonly anim: WeaponAnim;
  readonly orbTarget: { x: number; y: number };
  readonly gunX: number;
  readonly gunY: number;
  time: number;
  shotsFired: number;
  /** Rounds left / per stage: the SUPER SOAKER's tank gauge reads them. */
  ammoLeft: number;
  ammoTotal: number;
  weaponId: WeaponId;
  readonly shots: Projectile[];
  addFX(f: FX): void;
  after(delay: number, fn: () => void): void;
  shake(a: number): void;
  flashScreen(color: string, a: number): void;
}

/** What the generated wheel code (`setSevenWheel.ts`) reads from its host. */
export interface SevenWheelHost {
  readonly particles: Particles;
  readonly wheel: SevenWheel;
  readonly stuck: StuckItem[];
  readonly wheelGone: boolean;
  readonly decals: Decal[];
  /** Live wheel speed in rad/s (slide 3's own `SPIN` is a constant 1.9). */
  readonly spin: number;
  lens(x: number, y: number, r: number, s: number): void;
}

const NO_HOOKS: SevenHooks = {
  shake: () => {},
  paintWheel: () => {},
  wheel: () => ({ x: 0, y: 0, R: 0, angle: 0 }),
};

const restFeel = (): SevenFeel => ({
  bumpY: 0, bumpV: 0, rim: 0, rimColor: 'rgba(255,255,255,',
  pulseS: 0, pulseV: 0, flashA: 0, flashColor: '255,255,255', stop: 0,
});

/** One refraction request of slide 3's `lens()` (cleared every frame). */
interface LensReq { x: number; y: number; r: number; s: number }

export class SetSevenFx implements SevenHost, SevenWheelHost {
  particles = new Particles();
  anim: WeaponAnim = newAnim();
  /** Slide-3 `after()` timers, in seconds. */
  timers: { t: number; fn: () => void }[] = [];
  /** Screen-space FX (muzzle flashes, lights, arcs, rings…). */
  fx: FX[] = [];
  /** Wheel-space FX (cracks glowing, rim spots): drawn from the wheel centre. */
  wheelFx: FX[] = [];
  /** Reused scratch for overlapping yellow Plasma lightning. */
  private wheelBoltScratch: BatchableWheelLightning[] = [];
  private wheelLightningCache = new WheelLightningCache();
  /** Rounds slide 3's recipes created since the last `takeShots()`. */
  shots: Projectile[] = [];
  /** Rounds stuck in the wheel — slide 3's own `drawStuckItem()` art. */
  stuck: StuckItem[] = [];
  /** Slide 3's decals: goo, wet and poison stains and smouldering scorch. */
  decals: Decal[] = [];
  /**
   * Rounds slide 1 has already resolved and stopped carrying.
   *
   * Slide 3 never stops updating a round when it lands: the shotgun's pellet
   * shower, the minigun drum, the water jet and every `trail()` keep running
   * until the round leaves the screen. Slide 1 removes its carrier the frame
   * the round sticks, so those rounds are handed back here and live out their
   * own short life on slide 3's clock.
   */
  released: Projectile[] = [];
  /** The moving point slide-3's `pull` particles chase. */
  orbTarget = { x: 0, y: 0 };
  time = 0;
  shotsFired = 0;
  ammoLeft = 8;
  ammoTotal = 8;
  weaponId: WeaponId = 'snowball';
  wheelGone = false;
  gunX = 210;
  gunY = 575;
  /** Live wheel speed (rad/s), for the drips that fly off the turning rim. */
  spin = 0;
  /** Slide 3's own hit reaction (see `SevenFeel`). */
  feel: SevenFeel = restFeel();
  /**
   * True while a slide-3 round bursts on the rock, the chest or the bonus
   * ring: its burst, light, shake and sound happen there, but nothing lands in
   * (or paints, or bounces) a wheel that is not on screen.
   */
  special = false;
  /** The round a `special` impact would have stuck (slide 1 embeds it in the rock). */
  captured: StuckItem | null = null;
  /** This frame's `lens()` requests, applied by `applyLens()`. */
  lensReq: LensReq[] = [];
  private lensCanvas: HTMLCanvasElement | null = null;
  private lastAngle: number | null = null;

  private hooks: SevenHooks;

  /** Slide-3's wheel object, kept in sync with slide 1 every frame. */
  readonly wheel: SevenWheel = {
    x: 210, y: 0, R: 0, angle: 0, bumpY: 0, bumpV: 0, flash: 0,
    flashColor: 'rgba(255,255,255,', scale: 1, intro: 1, shakeT: 0, shakeX: 0,
  };

  /** The game shim handed to slide 3's projectile constructors. */
  readonly game: SevenGame;

  constructor(hooks: SevenHooks = NO_HOOKS) {
    this.hooks = hooks;
    const host = this;
    this.game = {
      particles: host.particles,
      get anim() { return host.anim; },
      wheel: host.wheel,
      get wheelGone() { return host.wheelGone; },
      get stuck() { return host.stuck; },
      get time() { return host.time; },
      addFX: (f) => host.addFX(f),
      addWheelFX: (f) => { if (!host.special) host.addWheel(f); },
      addDecal: (d) => host.addDecal(d),
      paint: (fn) => { if (!host.special) host.hooks.paintWheel(fn, host.wheel.R); },
      lens: (x, y, r, s) => host.lens(x, y, r, s),
      shake: (a) => host.shake(a),
      flashScreen: (color, a) => host.flashScreen(color, a),
      wheelImpact: (power, color = 'rgba(255,255,255,') => host.wheelImpact(power, color),
      hitStop: (t) => host.hitStop(t),
      after: (delay, fn) => host.after(delay, fn),
      pulseWheel: (a) => host.pulseWheel(a),
      landed: (it) => host.landed(it),
      // Slide 1 owns the flight path and the hit test (spikes, coins,
      // obstacles, boss health), so slide 3 must not resolve the shot itself.
      collide: () => {},
    };
  }

  /** Swap the hooks when slide 1 rebuilds its callbacks. */
  setHooks(hooks: SevenHooks) {
    this.hooks = hooks;
  }

  /** Slide 3's game object, typed for its own constructors. */
  get g(): Game {
    return this.game as unknown as Game;
  }

  addFX(f: FX) {
    this.fx.push(f);
    return f;
  }

  addWheel(f: FX) {
    this.wheelFx.push(f);
    return f;
  }

  shake(a: number) {
    this.hooks.shake(a);
  }

  /** Slide 3's `flashScreen()`: the colour is replaced, the strength kept at its max. */
  flashScreen(color: string, a: number) {
    this.feel.flashColor = color;
    this.feel.flashA = Math.max(this.feel.flashA, a);
  }

  /** Slide 3's `wheelImpact()`: a kick into the wheel's bounce spring and a rim flash. */
  wheelImpact(power: number, color = 'rgba(255,255,255,') {
    if (this.special) return;
    this.feel.bumpV -= power * 26;
    this.feel.rim = 1;
    this.feel.rimColor = color;
  }

  /** Slide 3's `pulseWheel()` (the shrink and grow rays): a visual size pulse. */
  pulseWheel(a: number) {
    if (this.special) return;
    this.feel.pulseS = a;
    this.feel.pulseV = 0;
  }

  /** Do not slow the whole world on every successful shot. */
  hitStop(_t: number) {
    // The original 30–150ms stop ran everything at 22%, making a hit look like
    // a dropped frame even at a stable FPS. Wheel bounce, flash, shake, sound
    // and the full particle burst are independent and continue unchanged.
  }

  /** Slide 3's `lens()`: a refraction applied over the frame (see `applyLens`). */
  lens(x: number, y: number, r: number, s: number) {
    this.lensReq.push({ x, y, r, s });
  }

  after(delay: number, fn: () => void) {
    this.timers.push({ t: delay, fn });
  }

  /**
   * Slide-3's `landed()`: the round is now part of the wheel. Slide 1 has
   * already scored the hit and stored its own collision entry, so this only
   * keeps the visible half of it — the stuck weapon art slide 3 draws.
   */
  landed(it: StuckItem) {
    if (this.special) {
      this.captured = it;
      return;
    }
    it.world.x = this.wheel.x + Math.cos(it.angle + this.wheel.angle) * this.wheel.R;
    it.world.y = this.wheel.y + this.wheel.bumpY + Math.sin(it.angle + this.wheel.angle) * this.wheel.R;
    this.stuck.push(it);
    this.stuck.sort((a, b) => b.protrude - a.protrude);
  }

  /** Slide-3's `addDecal()`: a stain that lives (and drips) on the wheel face. */
  addDecal(d: Decal) {
    if (this.special) return;
    this.decals.push(d);
  }

  /** Refresh the wheel mirror from slide 1 before running slide-3 code. */
  syncWheel() {
    const w = this.hooks.wheel();
    this.wheel.x = w.x;
    this.wheel.y = w.y;
    this.wheel.R = w.R;
    this.wheel.angle = w.angle;
    this.wheel.bumpY = this.feel.bumpY;
  }

  /** True while slide 3 still has something to draw or animate. */
  get busy(): boolean {
    const f = this.feel;
    return this.particles.list.length > 0 || this.fx.length > 0 || this.timers.length > 0
      || this.wheelFx.length > 0 || this.shots.some((p) => p.alive) || this.stuck.length > 0
      || this.released.length > 0 || this.decals.length > 0 || f.rim > 0 || f.flashA > 0
      || f.stop > 0 || Math.abs(f.bumpY) > 0.01 || Math.abs(f.bumpV) > 0.5 || Math.abs(f.pulseS) > 0.001;
  }

  /** Hand a round slide 1 just resolved back to slide 3's own clock. */
  release(shot: Projectile) {
    this.released.push(shot);
  }

  clear() {
    this.particles.clear();
    this.fx.length = 0;
    this.timers.length = 0;
    this.wheelFx.length = 0;
    this.wheelBoltScratch.length = 0;
    this.wheelLightningCache.clear();
    this.shots.length = 0;
    this.stuck.length = 0;
    this.decals.length = 0;
    this.released.length = 0;
    this.lensReq.length = 0;
    this.feel = restFeel();
    this.wheel.bumpY = 0;
    this.lastAngle = null;
  }

  /**
   * Overlapping rapid-fire impacts can otherwise accumulate hundreds of old
   * particles. Only under pressure, retire faded cosmetic debris first and
   * then the oldest debris; keep the fresh impact. Never trim custom art,
   * rings/glows, targets, payloads or particles with callbacks. The budget is
   * best-effort when protected effects alone exceed it.
   */
  private trimCosmeticParticles() {
    const budget = this.weaponId === 'golden' ? GOLDEN_PARTICLE_BUDGET : SLIDE_THREE_PARTICLE_BUDGET;
    const list = this.particles.list;
    let excess = list.length - budget;
    if (excess <= 0) return;
    for (let pass = 0; pass < 2; pass++) {
      const fadedOnly = pass === 0;
      let write = 0;
      for (let i = 0; i < list.length; i++) {
        const p = list[i];
        const cosmetic = p.k === K.SPARK || p.k === K.STAR || p.k === K.SMOKE
          || p.k === K.CHIP || p.k === K.FLAKE || p.k === K.EMBER;
        if (excess > 0 && cosmetic && !p.die && !p.draw && !p.target && p.data == null
          && (!fadedOnly || p.life <= p.max * 0.55)) {
          excess--;
          continue;
        }
        list[write++] = p;
      }
      list.length = write;
      if (excess <= 0) break;
    }
  }

  /**
   * One frame of slide-3 time, in the order its own `update()` runs it: the
   * lens list is cleared, the timers fire (in the order they were set), the
   * size pulse, the wheel's bounce spring and rim flash move, the stuck rounds
   * ride the rim (smoking, smouldering, bending light), the gun's springs and
   * its idle ambience (`animate`), then the particles, the FX, the rounds slide
   * 1 already let go, the decals' drips, and the screen flash fades.
   */
  update(dt: number, animate = false) {
    this.time += dt;
    this.lensReq.length = 0;
    if (this.timers.length) {
      const run: { t: number; fn: () => void }[] = [];
      this.timers = this.timers.filter((t) => {
        t.t -= dt;
        if (t.t <= 0) {
          run.push(t);
          return false;
        }
        return true;
      });
      for (const t of run) t.fn();
    }
    const f = this.feel;
    f.pulseV += (-130 * f.pulseS - 9 * f.pulseV) * dt;
    f.pulseS += f.pulseV * dt;
    f.bumpV += (-420 * f.bumpY - 22 * f.bumpV) * dt;
    f.bumpY += f.bumpV * dt;
    this.wheel.bumpY = f.bumpY;
    f.rim = Math.max(0, f.rim - dt * 7);
    // The live wheel speed the rim drips inherit (slide 3 uses its fixed SPIN).
    const a = this.wheel.angle;
    if (this.lastAngle !== null && dt > 0) {
      const d = ((a - this.lastAngle + Math.PI) % TAU + TAU) % TAU - Math.PI;
      this.spin = d / dt;
    }
    this.lastAngle = a;
    updateSevenStuck(this, dt);
    if (animate) updateSevenAnim(this, dt);
    this.particles.update(dt);
    this.trimCosmeticParticles();
    for (const fx of this.fx) fx.update(dt);
    this.fx = this.fx.filter((fx) => !fx.done);
    for (const fx of this.wheelFx) fx.update(dt);
    this.wheelFx = this.wheelFx.filter((fx) => !fx.done);
    this.shots = this.shots.filter((p) => p.alive);
    // Rounds that outlived slide 1's carrier keep their own flight (and their
    // sub-projectiles) until they die, exactly like slide 3.
    for (const p of this.released) p.update(dt);
    this.released = this.released.filter((p) => p.alive);
    updateSevenDecals(this, dt);
    f.flashA = Math.max(0, f.flashA - dt * 2.2);
  }

  /** Slide 3 draws its non-additive particles first… */
  draw(ctx: CanvasRenderingContext2D) {
    // A shot can add its impact after update(), so enforce the same limit
    // before rendering that very frame rather than waiting for the next tick.
    this.trimCosmeticParticles();
    this.particles.draw(ctx, false);
  }

  /** …then the additive ones and every FX object on top. */
  drawFront(ctx: CanvasRenderingContext2D) {
    this.particles.draw(ctx, true);
    for (const f of this.fx) f.draw(ctx);
    // Slide 3 drops a round the frame its `hit()` kills it; only the ones that
    // live on (the harpoon reeling in, the water jet, the drum) are drawn.
    for (const p of this.released) if (p.alive) p.draw(ctx);
  }

  /**
   * Stuck rounds, in a context already centred on the wheel and turned with
   * it. Slide 3 draws the ordinary ones *before* its wheel face (so the part
   * buried in the wood is hidden) and the `front` ones after it.
   */
  drawStuck(ctx: CanvasRenderingContext2D, radius: number, front: boolean) {
    for (const it of this.stuck) {
      if (!!it.front !== front) continue;
      ctx.save();
      ctx.rotate(it.angle);
      drawStuckItem(ctx, it, radius, this.time);
      ctx.restore();
    }
  }

  /** Decals, then the wheel-space FX clipped to the wheel — over the face. */
  drawFace(ctx: CanvasRenderingContext2D, radius: number) {
    drawSevenDecals(this, ctx);
    if (this.wheelFx.length) {
      ctx.save();
      ctx.beginPath();
      ctx.arc(0, 0, radius, 0, TAU);
      ctx.clip();
      const bolts = this.wheelBoltScratch;
      bolts.length = 0;
      for (const f of this.wheelFx) if (f instanceof BatchableWheelLightning) bolts.push(f);
      if (bolts.length <= 7) {
        // The first hit is precisely the original Plasma Gun rendering.
        this.wheelLightningCache.clear();
        for (const f of this.wheelFx) f.draw(ctx);
        ctx.restore();
      } else {
        for (const f of this.wheelFx) if (!(f instanceof BatchableWheelLightning)) f.draw(ctx);
        ctx.restore();
        this.wheelLightningCache.draw(ctx, bolts, radius, this.time);
      }
      bolts.length = 0;
    }
  }

  /** The rim flash `wheelImpact()` leaves: slide 3 fills the face at 0.6 × it. */
  drawRim(ctx: CanvasRenderingContext2D, radius: number) {
    if (this.feel.rim <= 0) return;
    ctx.fillStyle = `${this.feel.rimColor}${(this.feel.rim * 0.6).toFixed(3)})`;
    ctx.beginPath();
    ctx.arc(0, 0, radius - 0.5, 0, TAU);
    ctx.fill();
  }

  /** Slide 3's full-screen flash (drawn over the scene, unshaken). */
  drawFlash(ctx: CanvasRenderingContext2D, w: number, h: number) {
    if (this.feel.flashA <= 0) return;
    ctx.fillStyle = `rgba(${this.feel.flashColor},${this.feel.flashA.toFixed(3)})`;
    ctx.fillRect(0, 0, w, h);
  }

  /** Everything on the wheel at once (cards, tests): rounds, decals, FX. */
  drawWheel(ctx: CanvasRenderingContext2D, cx: number, cy: number, radius = this.wheel.R, rot = this.wheel.angle) {
    if (!this.wheelFx.length && !this.stuck.length && !this.decals.length) return;
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(rot);
    this.drawStuck(ctx, radius, false);
    this.drawFace(ctx, radius);
    this.drawStuck(ctx, radius, true);
    ctx.restore();
  }

  /**
   * Slide 3's `applyLens()`: each request bends what is already on the canvas
   * under it — ten nested rings, each a slightly bigger, slightly turned copy —
   * plus its faint violet rim. `source` is the canvas `ctx` draws into.
   */
  applyLens(ctx: CanvasRenderingContext2D, source: HTMLCanvasElement) {
    if (!this.lensReq.length) return;
    const m = typeof ctx.getTransform === 'function' ? ctx.getTransform() : null;
    if (!m || !source) return;
    const k = Math.hypot(m.a, m.b) || 1;
    for (const l of this.lensReq) {
      const size = Math.ceil(l.r * 2 * k);
      if (size < 4) continue;
      let sx = Math.round(m.a * (l.x - l.r) + m.c * (l.y - l.r) + m.e);
      let sy = Math.round(m.b * (l.x - l.r) + m.d * (l.y - l.r) + m.f);
      let sw = size;
      let sh = size;
      let dx = 0;
      let dy = 0;
      if (sx < 0) { dx = -sx; sw += sx; sx = 0; }
      if (sy < 0) { dy = -sy; sh += sy; sy = 0; }
      if (sx + sw > source.width) sw = source.width - sx;
      if (sy + sh > source.height) sh = source.height - sy;
      if (sw <= 2 || sh <= 2) continue;
      const lensCanvas = (this.lensCanvas ??= document.createElement('canvas'));
      // The animated lens radius changes almost every frame. Resizing a
      // canvas reallocates/clears its backing surface and synchronizes the
      // renderer; grow a reusable surface instead and sample only this lens's
      // active square. This keeps all nine refraction rings at full resolution.
      if (lensCanvas.width < size || lensCanvas.height < size) {
        const capacity = 2 ** Math.ceil(Math.log2(size));
        lensCanvas.width = capacity;
        lensCanvas.height = capacity;
      }
      const lc = lensCanvas.getContext('2d');
      if (!lc) continue;
      lc.clearRect(0, 0, size, size);
      lc.drawImage(source, sx, sy, sw, sh, dx, dy, sw, sh);
      const rings = 10;
      for (let i = 1; i < rings; i++) {
        const f = i / rings;
        const rr = l.r * (1 - f);
        ctx.save();
        ctx.beginPath();
        ctx.arc(l.x, l.y, rr, 0, TAU);
        ctx.clip();
        ctx.translate(l.x, l.y);
        ctx.rotate(l.s * 1.2 * f * f + this.time * l.s * 0.9 * f);
        const z = 1 + l.s * 0.45 * f;
        ctx.scale(z, z);
        ctx.drawImage(lensCanvas, 0, 0, size, size, -l.r, -l.r, l.r * 2, l.r * 2);
        ctx.restore();
      }
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      ctx.strokeStyle = `rgba(200,150,255,${(0.18 * Math.min(1, l.s)).toFixed(3)})`;
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.arc(l.x, l.y, l.r * 0.55, 0, TAU);
      ctx.stroke();
      ctx.restore();
    }
  }

  /**
   * The star pickup wipes the screen.
   *
   * Slide 1 drops every carrier it was flying, but a round it had already
   * resolved keeps flying on slide 3's own layer (`released`), so it has to go
   * too — otherwise the screen the star just cleared stays full of slide-3
   * rounds.
   */
  sweepCarried() {
    this.released.length = 0;
  }

  /**
   * Take the shots a generated recipe just created. They keep the exact muzzle
   * position slide 3 gave them (`my - 6`, `my + 40` for the slingshot pouch,
   * `my - 38` for the blowpipe…), so nothing has to be re-derived here.
   */
  takeShots(): Projectile[] {
    const made = this.shots;
    this.shots = [];
    return made;
  }
}

/**
 * A still of the slide-7 round at `age` seconds after it left the muzzle, used
 * by the picker's effect card so \"Baru\" shows the real SET 2..5 projectile —
 * slide 7's own `draw()` for that weapon.
 */
export function drawSetSevenShotShell(
  c: CanvasRenderingContext2D,
  id: SlideThreeId,
  age: number,
  travel = 0,
) {
  const fx = new SetSevenFx();
  fx.weaponId = id;
  fx.shotsFired = 1;
  FIRE_RECIPES[id](fx, 0, 0);
  // METEOR, MOONBEAM, STORM and friends release their round a fraction of a
  // second after the trigger, exactly like slide 7: run its timers first.
  for (let i = 0; i < 40 && !fx.shots.length; i++) fx.update(1 / 60);
  const shot = fx.shots[0];
  if (!shot) return;
  shot.x = 0;
  shot.y = -travel;
  shot.age = age;
  c.save();
  shot.draw(c);
  c.restore();
}
